<?php
declare(strict_types=1);
require __DIR__.'/support.php';
function slotPage(?array $after=null,int $maximum=3,array $columns=['id','body','password','tag']):array{return ['table'=>'snapshot_test','key'=>['scope'=>'tenant'],'columns'=>$columns,'page'=>true,'maximum'=>$maximum,'after'=>$after];}
$mysql=($argv[1]??'')==='mysql';
snapshotCase($mysql,static function(InboxTestConnection $pdo,PDO $observer,string $dir):void{
    foreach([['tenant',1,"a\0b",null,'one'],['tenant',2,'','','two'],['tenant',3,"\xff\0\xfe",'secret-hash','three'],['tenant',4,'four',null,'four'],['tenant',5,'five',null,'five'],['other',1,'foreign',null,'other']] as $row){snapshotInsert($pdo,$row[0],$row[1],$row[2],$row[3],$row[4]);}
    $source=snapshotSource($pdo);$digest=$source->digest();$view=$source->capture(['slots'=>slotPage(),'total'=>['table'=>'snapshot_test','key'=>['scope'=>'tenant'],'columns'=>[],'count'=>true],'point'=>['table'=>'snapshot_test','key'=>['scope'=>'tenant','id'=>2],'columns'=>['body','password']]]);
    Check::same($digest,$view->digest());Check::same(true,$view->matches($source));$page=$view->page('slots');Check::same(5,$page['total']);Check::same(3,$page['limit']);Check::same(true,$page['more']);Check::same(['scope'=>'tenant','id'=>3],$page['cursor']);Check::same([1,2,3],array_column($page['rows'],'id'));Check::same("a\0b",$page['rows'][0]['body']);Check::same(null,$page['rows'][0]['password']);Check::same('',$page['rows'][1]['body']);Check::same('',$page['rows'][1]['password']);Check::same("\xff\0\xfe",$page['rows'][2]['body']);Check::same(['count'=>5],$view->row('total'));Check::same(['body'=>'','password'=>''],$view->row('point'));
    $second=$source->capture(['slots'=>slotPage($page['cursor'])]);$last=$second->page('slots');Check::same($digest,$second->digest());Check::same([4,5],array_column($last['rows'],'id'));Check::same(5,$last['total']);Check::same(false,$last['more']);Check::same(['scope'=>'tenant','id'=>5],$last['cursor']);
    $end=$source->capture(['slots'=>slotPage($last['cursor'])])->page('slots');Check::same([],$end['rows']);Check::same(false,$end['more']);Check::same($last['cursor'],$end['cursor']);Check::same(5,$end['total']);
    $copy=$view->page('slots');$copy['rows'][0]['body']='modified';$copy['cursor']['id']=999;Check::same("a\0b",$view->page('slots')['rows'][0]['body']);Check::same(3,$view->page('slots')['cursor']['id']);Check::same(true,$view->same($source->capture(['slots'=>slotPage(),'total'=>['table'=>'snapshot_test','key'=>['scope'=>'tenant'],'columns'=>[],'count'=>true],'point'=>['table'=>'snapshot_test','key'=>['scope'=>'tenant','id'=>2],'columns'=>['body','password']]])));
    Check::throws(SoSecurity\Exception\ConfigurationException::class,static function()use($view):void{$view->row('slots');});Check::throws(SoSecurity\Exception\ConfigurationException::class,static function()use($view):void{$view->page('point');});
    $empty=slotPage();$empty['key']=['scope'=>'absent'];$empty=$source->capture(['slots'=>$empty])->page('slots');Check::same(['rows'=>[],'total'=>0,'limit'=>3,'more'=>false,'cursor'=>null],$empty);
    $rows=$observer->query('SELECT * FROM snapshot_test ORDER BY scope,id')->fetchAll(PDO::FETCH_ASSOC);snapshotReason('account.snapshot_cursor',static function()use($source):void{$source->capture(['slots'=>slotPage(['scope'=>'tenant','id'=>999])]);});Check::same($rows,$observer->query('SELECT * FROM snapshot_test ORDER BY scope,id')->fetchAll(PDO::FETCH_ASSOC));Check::same($digest,$source->capture(['slots'=>slotPage()])->digest());
});
snapshotCase($mysql,static function(InboxTestConnection $pdo,PDO $observer,string $dir):void{
    for($i=1;$i<=173;++$i){snapshotInsert($pdo,'tenant',$i,'value-'.$i,null,'tag');}$source=snapshotSource($pdo);$digest=$source->digest();$first=$source->capture(['slots'=>slotPage(null,8,['id'])])->page('slots');Check::same(173,$first['total']);Check::same(range(1,8),array_column($first['rows'],'id'));Check::same(true,$first['more']);$last=$source->capture(['slots'=>slotPage(['scope'=>'tenant','id'=>170],8,['id'])]);Check::same($digest,$last->digest());Check::same([171,172,173],array_column($last->page('slots')['rows'],'id'));Check::same(false,$last->page('slots')['more']);
});
echo 'PASS same-snapshot bounded slot pages: '.Check::$assertions.' assertions '.($mysql?'MySQL':'SQLite').' PHP '.PHP_VERSION."\n";
